/***
 * MARK: normalizeStageType
 * @description Normalizes stage types to the authoritative types ('agent', 'human', 'ci', 'merge').
 * Legacy types are mapped: 'review' -> 'human', 'script' -> 'ci',
 * 'deploy' -> 'ci' (the deploy pipeline stage type was removed — a stage
 * whose command runs the deploy script is an ordinary ci stage with no
 * special runtime), 'custom'/other -> 'agent'.
 * @example normalizeStageType('review') => 'human'
 * @example normalizeStageType('deploy') => 'ci'
 * @param {string} [type]
 * @returns {'agent'|'human'|'ci'|'merge'}
 ***/
export function normalizeStageType(type) {
	if (!type || typeof type !== "string") return "agent";
	const lower = type.trim().toLowerCase();
	if (lower === "human" || lower === "review") return "human";
	if (lower === "ci" || lower === "script" || lower === "deploy") return "ci";
	if (lower === "merge") return "merge";
	if (lower === "agent") return "agent";
	return "agent";
}

/***
 * MARK: normalizeStageSkills
 * @description Normalizes a stage's optional `skills` attachment list. Unknown fields
 *   on each attachment pass through untouched (non-declarative tolerance); only the
 *   authoritative fields are coerced: `name` (trimmed), `mode` ('direct'|'option'),
 *   and `config` (plain object). Entries without a usable name are dropped.
 *   Returns `undefined` when `skills` is absent so legacy stages are untouched.
 * @example normalizeStageSkills([{ name: 'a', mode: 'OPTION', config: { x: 1 }, extra: true }])
 *   => [{ name: 'a', mode: 'option', config: { x: 1 }, extra: true }]
 * @param {Array|undefined} [skills]
 * @returns {Array<Object>|undefined}
 ***/
export function normalizeStageSkills(skills) {
	if (skills === undefined || skills === null) return undefined;
	if (!Array.isArray(skills)) return [];
	return skills
		.filter(
			(s) =>
				s && typeof s === "object" && typeof s.name === "string" && s.name.trim(),
		)
		.map((s) => {
			const normalized = { ...s, name: s.name.trim() };
			if (s.mode !== undefined) {
				normalized.mode =
					typeof s.mode === "string" && s.mode.trim().toLowerCase() === "option"
						? "option"
						: "direct";
			}
			if (s.config !== undefined) {
				normalized.config =
					s.config && typeof s.config === "object" && !Array.isArray(s.config)
						? s.config
						: {};
			}
			return normalized;
		});
}

/***
 * MARK: normalizeStage
 * @description Normalizes a single stage object ensuring stage type is strictly 'agent', 'human', or 'ci'.
 *   The optional per-stage `harness` override (blank/absent means "inherit the
 *   project harness") is trimmed; a blank or non-string value clears it
 *   (undefined) so persistence drops the key. The id itself is NOT validated
 *   here: an unknown harness warns visibly at session time and degrades to the
 *   project harness (see resolveHarnessForProject).
 *   CI stages additionally carry an optional `runOnBranch` mode ('task'
 *   default | 'primary' | 'custom', legacy 'main' maps to 'primary') and a
 *   `customBranch` name (trimmed; blank clears it). Legacy spellings
 *   `executionBranch`/`customExecutionBranch` are migrated to the canonical
 *   names and dropped so storage converges on the first save.
 *   Any stage may carry an optional `runnerPolicy`
 *   (`{ mode: 'allow' | 'block', runners: [...] }`) naming which Runners may
 *   take it; absent or empty means every Runner may (see
 *   normalizeStageRunnerPolicy).
 * @example normalizeStage({ id: '1', name: 'Test', type: 'script' }) => { id: '1', name: 'Test', type: 'ci' }
 * @example normalizeStage({ id: '1', harness: '  custom  ' }).harness => 'custom'
 * @param {Object} stage
 * @returns {Object}
 ***/
export function normalizeStage(stage) {
	if (!stage || typeof stage !== "object") return stage;
	// The removed `deploy` type folds into `ci` with no special runtime: a
	// legacy deploy stage keeps whatever command it carried (or no command,
	// like any other command-less ci stage) and runs as ordinary CI. The
	// default deploy command is never stamped — an explicit command is the
	// only thing that makes a stage run the deploy script.
	const normalized = {
		...stage,
		type: normalizeStageType(stage.type),
	};
	// Optional per-stage skills (additive): normalise only when present so legacy
	// stage objects round-trip byte-identically.
	if (stage.skills !== undefined) {
		const skills = normalizeStageSkills(stage.skills);
		if (skills !== undefined) normalized.skills = skills;
		else delete normalized.skills;
	}
	// Optional per-stage tags (additive): normalise only when present so legacy
	// stage objects round-trip byte-identically.
	if (stage.tags !== undefined) {
		const tags = normalizeStageTags(stage.tags);
		if (tags !== undefined) normalized.tags = tags;
		else delete normalized.tags;
	}
	// Optional per-stage Runner allow/block list (additive): normalise only
	// when present so legacy stage objects round-trip byte-identically. An
	// empty or malformed policy drops the key (unrestricted) so stored
	// stages stay clean; unknown modes are refused with 400 at the save
	// boundary before they ever reach here.
	if (stage.runnerPolicy !== undefined) {
		const runnerPolicy = normalizeStageRunnerPolicy(stage.runnerPolicy);
		if (runnerPolicy !== undefined) normalized.runnerPolicy = runnerPolicy;
		else delete normalized.runnerPolicy;
	}
	// Optional per-stage harness override (additive): same explicit-choice-only
	// rule as project.harness — blank clears it (undefined).
	if (stage.harness !== undefined) {
		normalized.harness =
			typeof stage.harness === "string" && stage.harness.trim()
				? stage.harness.trim()
				: undefined;
	}
	// Optional per-stage CI branch execution mode (additive):
	// 'task' (default, absent) | 'primary' (project default branch) | 'custom'.
	// The 'main' value and the executionBranch/customExecutionBranch key names
	// are legacy spellings from the same feature's first iteration — mapped
	// here so hand-edited or in-flight configs converge on the canonical
	// fields (the legacy keys are dropped, never re-saved).
	const RUN_ON_BRANCH = new Set(["task", "primary", "custom"]);
	const rawRunOnBranch =
		stage.runOnBranch !== undefined ? stage.runOnBranch : stage.executionBranch;
	if (rawRunOnBranch !== undefined) {
		const v =
			typeof rawRunOnBranch === "string" ? rawRunOnBranch.trim().toLowerCase() : "";
		const mapped = v === "main" ? "primary" : v;
		normalized.runOnBranch = RUN_ON_BRANCH.has(mapped) ? mapped : "task";
	}
	const rawCustomBranch =
		stage.customBranch !== undefined ? stage.customBranch : stage.customExecutionBranch;
	if (rawCustomBranch !== undefined) {
		normalized.customBranch =
			typeof rawCustomBranch === "string" && rawCustomBranch.trim()
				? rawCustomBranch.trim()
				: undefined;
	}
	delete normalized.executionBranch;
	delete normalized.customExecutionBranch;
	// Retired (was DA9): every command stage runs on a Runner — the backend
	// never executes stage commands, so no stage is ever host-only. Strip
	// any legacy hostOnly stamp so previously stored stages rejoin fleet
	// dispatch on the next normalization.
	delete normalized.hostOnly;
	return normalized;
}

/***
 * MARK: migrateMergeDeployStages
 * @description Migrates composite "Merge and deploy" stages — a merge stage
 *   that carries a command — into a git-only merge stage plus a dedicated
 *   command CI stage inserted immediately after it, in the same list and
 *   order. The merge stage only performs git operations now, so the command
 *   moves to its own ordinary ci stage: git failures and command failures
 *   can never mix again. The inserted stage keeps the recorded command
 *   verbatim (including a deploy-script command, which runs as ordinary CI
 *   with normal failback) and fails back to the merge stage ("previous").
 *
 *   Idempotent: a merge stage without a command is left untouched, and the
 *   inserted deploy stage reuses the deterministic id `<mergeId>-deploy`, so
 *   re-running the migration (every project load/save normalizes again)
 *   never duplicates it. A non-deploy post-merge command is dropped from the
 *   merge stage without an inserted stage (deprecated: see DEPRECATIONS.md).
 * @example migrateMergeDeployStages([{ id: 'm', type: 'merge', command: './deploy.sh --prod' }])
 *   => [{ id: 'm', type: 'merge' }, { id: 'm-deploy', type: 'ci', command: './deploy.sh --prod' }]
 * @param {Array<Object>} [stages] - Already type-normalized stages.
 * @returns {Array<Object>} The migrated stage list (same order + inserted deploy stages).
 ***/
export function migrateMergeDeployStages(stages) {
	if (!Array.isArray(stages)) return [];
	const existingIds = new Set(
		stages.filter((s) => s && typeof s === "object").map((s) => String(s.id)),
	);
	const out = [];
	for (const stage of stages) {
		const isMergeStage =
			stage &&
			typeof stage === "object" &&
			String(stage.type || "").toLowerCase() === "merge";
		const command =
			isMergeStage &&
			((typeof stage.command === "string" && stage.command.trim()) ||
				(typeof stage.script === "string" && stage.script.trim()))
				? stage.command || stage.script
				: "";
		if (!isMergeStage || !command) {
			out.push(stage);
			continue;
		}
		// Strip the command: a merge stage is git-only and ignores commands.
		const mergeStage = { ...stage };
		delete mergeStage.command;
		delete mergeStage.script;
		// A name that advertised the composite ("Merge and deploy") must
		// not lie about the now git-only stage.
		const name = String(mergeStage.name || "");
		if (/merge/i.test(name) && /deploy/i.test(name)) {
			mergeStage.name = "Merge";
		}
		out.push(mergeStage);
		if (!isDeployCommand(command)) continue; // dropped, deprecated
		const deployStageId = `${String(mergeStage.id || "merge")}-deploy`;
		if (existingIds.has(deployStageId)) continue; // already migrated
		out.push({
			id: deployStageId,
			name: "Deploy",
			type: "ci",
			command,
			paused: false,
			failback: "previous",
		});
	}
	return out;
}

/***
 * MARK: normalizeStages
 * @description Normalizes an array of stage objects ensuring legacy types
 *   are migrated, then migrates composite merge-and-command stages into a
 *   git-only merge stage plus a dedicated command CI stage (see
 *   migrateMergeDeployStages).
 * @example normalizeStages([{ type: 'review' }]) => [{ type: 'human' }]
 * @example normalizeStages([{ type: 'merge', command: './deploy.sh --prod' }]).length => 2
 * @param {Array<Object>} [stages]
 * @returns {Array<Object>}
 ***/
export function normalizeStages(stages) {
	if (!Array.isArray(stages)) return [];
	return migrateMergeDeployStages(stages.map(normalizeStage));
}

import { RUNNER_PROTOCOL } from "../runnerRegistry.js";
import { runnerApiCompatible } from "./runnerApiCompat.js";
import { operatorConfigVerdict } from "./operatorConfigVerdict.js";
import { stageRunnerPolicyVerdict } from "../../../shared/stageRunnerPolicy.js";

/***
 * MARK: runnerMatches
 * @description Decides whether one Runner registration can take a task with
 *   the given requirements: active status, not paused, fresh heartbeat
 *   (staleness expiry), v1 protocol, runnable flag, harness id, model
 *   offering, tier membership, and disk headroom floor. Returns
 *   `{ ok, reason }` — the
 *   reason code is loud by design (step-6 NO_CAPABLE_RUNNER diagnostics
 *   and the monitor surface distinguish "no runners" from "runners that
 *   cannot take this job"). Alias requirements always miss here; WP-3.2
 *   resolves them centrally first. The last two gates are owner settings:
 *   the Runner's own `operatorConfig` first, then the stage's
 *   `runnerPolicy` (`RUNNER_NOT_ALLOWED` / `RUNNER_BLOCKED`) — owner
 *   settings keep a stable order so combined refusals always report the
 *   same reason.
 * @example runnerMatches(record, { harness: 'pi', tier: 'T1' }) => { ok: true, reason: 'MATCH' }
 * @param {Object} record - Registry record (`status`, `facts`, `lastSeenAt`, `capabilities`, plus the operator-owned `operatorConfig` the Runners settings screen persists).
 * @param {Object} req - Task requirements from `taskRequirements`.
 * @param {Object} [opts] - `{ now, staleAfterMs, minDiskHeadroomMb, projectId }` (`projectId` is the candidate's project, needed for the operator project-scope check; a scoped Runner with no project id on the candidate misses loudly instead of guessing).
 * @returns {Object} `{ ok, reason }`.
 ***/
export function runnerMatches(record = {}, req = {}, opts = {}) {
	const now = typeof opts.now === "number" ? opts.now : Date.now();
	const staleAfterMs =
		typeof opts.staleAfterMs === "number" && opts.staleAfterMs > 0
			? opts.staleAfterMs
			: 60000;
	const minDisk =
		typeof opts.minDiskHeadroomMb === "number" && opts.minDiskHeadroomMb >= 0
			? opts.minDiskHeadroomMb
			: 100;
	if (record.status !== "active") return { ok: false, reason: "NOT_ACTIVE" };
	if (record.paused === true) return { ok: false, reason: "PAUSED" };
	const seen = Date.parse(record.lastSeenAt || "");
	if (!Number.isFinite(seen) || now - seen > staleAfterMs) {
		return { ok: false, reason: "STALE_HEARTBEAT" };
	}
	const caps = record.capabilities || {};
	if (caps.runnable === false) return { ok: false, reason: "NOT_RUNNABLE" };
	const protocol =
		caps.versions?.protocol || record.facts?.versions?.protocol;
	if (protocol !== RUNNER_PROTOCOL) {
		return { ok: false, reason: "PROTOCOL_SKEW" };
	}
	const runnerApi = caps.versions?.api || record.facts?.versions?.api;
	if (!runnerApiCompatible(runnerApi).ok) {
		return { ok: false, reason: "PROTOCOL_SKEW" };
	}
	// Only the raw string marker (taskRequirements' `{ alias: name }`) is
	// unservable here. A resolved alias object (`{ name, targetIndex }`,
	// stamped by the route after central D3 resolution) carries the
	// concrete harness/model below and matches like any direct requirement.
	if (typeof req.alias === "string" && req.alias) {
		return { ok: false, reason: "ALIAS_UNRESOLVED" };
	}
	if (req.harness) {
		const offered = Array.isArray(caps.harnesses) ? caps.harnesses : [];
		if (!offered.some((h) => h && h.id === req.harness)) {
			return { ok: false, reason: "NO_HARNESS" };
		}
	}
	if (req.model) {
		const models = Array.isArray(caps.models) ? caps.models : [];
		if (!models.includes(req.model)) return { ok: false, reason: "NO_MODEL" };
	}
	if (req.tier) {
		const tiers = Array.isArray(caps.tiers) ? caps.tiers : [];
		if (!tiers.includes(req.tier)) return { ok: false, reason: "TIER_CEILING" };
	}
	if (caps.diskHeadroomMb !== null && caps.diskHeadroomMb !== undefined) {
		if (caps.diskHeadroomMb < minDisk) return { ok: false, reason: "DISK_LOW" };
	}
	// Operator-owned configuration (System Settings › Runners) refines an
	// otherwise-capable match without touching Runner-reported facts. It
	// sits after every health/capability gate so those keep their stable
	// reasons (a stale Runner still reports STALE_HEARTBEAT, never a scope
	// miss). The verdict itself lives in `operatorConfigVerdict`, shared
	// with the direct claim and integration lease routes so no claim path
	// can bypass the operator's settings.
	const operatorVerdict = operatorConfigVerdict(record, req, opts);
	if (!operatorVerdict.ok) return operatorVerdict;
	// Stage runnerPolicy (the stage settings allow/block list) is the final
	// gate: after the operator's own settings, so a Runner refused by both
	// always reports the operator reason, and after every health/capability
	// gate so those keep their stable reasons too.
	const policyVerdict = stageRunnerPolicyVerdict(req.runnerPolicy, record.runnerId);
	if (!policyVerdict.ok) return policyVerdict;
	return { ok: true, reason: "MATCH" };
}

import { ALIAS_HARNESS_ID } from "../../../shared/modelAliases.js";
import { normalizeStageRunnerPolicy } from "../../../shared/stageRunnerPolicy.js";
import { resolveHarnessName } from "../../agent/harnessRegistry.js";

/***
 * MARK: taskRequirements
 * @description Derives what a task's current stage needs from a Runner:
 *   harness (stage override else project default else configured default,
 *   same order as the embedded `resolveHarnessName`),
 *   model (stage else project default), and required tier (explicit
 *   stage/task tier else T1 for model-driven stages else T0). Stages whose
 *   harness is the `alias` virtual id resolved by the dispatch route in
 *   WP-3.2 (D3 central counters via `resolveAliasRequirement`, sharing the
 *   embedded smooth-WRR rotation) and are marked `{ alias }` so
 *   unresolvable aliases miss loudly instead of guessing. Only
 *   agent/review stages are Runner-runnable; command, ci, and merge
 *   stages are Runner-runnable too (the backend never executes stage
 *   commands) — only human stages stay embedded. The stage's normalized
 *   runnerPolicy rides along (present only when the stage restricts
 *   Runners) so every claim path enforces the same policy.
 * @example taskRequirements({ harness: 'pi' }, { currentStageId: 's1', stages: [{ id: 's1', type: 'agent' }] }) => { harness: 'pi', ... }
 * @param {Object} project - Project entity.
 * @param {Object} task - Task entity.
 * @returns {Object} `{ harness, model, tier, alias, runnableType, hostCommand, kind, stageId, runnerPolicy? }`.
 ***/
export function taskRequirements(project = {}, task = {}) {
	const stages = Array.isArray(task.stages)
		? task.stages
		: Array.isArray(project?.stages)
			? project.stages
			: [];
	const stage =
		stages.find((s) => String(s?.id) === String(task.currentStageId)) ||
		stages[0] ||
		{};
	const type = String(stage.type || "agent").toLowerCase();
	const kind = type === "ci" || type === "script" || type === "deploy" || type === "command" ? "ci" : type === "merge" ? "merge" : type;
	// Retired (was DA9): every command stage is Runner-runnable — the
	// backend never executes stage commands. `hostCommand` stays in the
	// returned shape (always false) so existing consumers keep working.
	const hostCommand = false;
	// Merge stages are Runner-runnable as leased `integrate` jobs (Step 4):
	// the dispatch route matches them like CI (no harness/model, T0) and
	// the integration lease — not a harness — is the fencing token.
	const runnableType = type === "agent" || type === "review" || kind === "ci" || kind === "merge";

	// Same order as the embedded run path (`resolveHarnessName`): stage
	// override → project default → configured default → built-in. Dispatch
	// must demand exactly what the engine would run, or every default-harness
	// host misses every task (NO_HARNESS) while embedded runs them fine.
	const rawHarness = resolveHarnessName(project, { harnessName: stage.harness });

	let alias = null;
	let harness = rawHarness;
	if (rawHarness === ALIAS_HARNESS_ID) {
		const name =
			typeof stage.model === "string" && stage.model.trim()
				? stage.model.trim()
				: typeof project?.defaultModel === "string" && project.defaultModel.trim()
					? project.defaultModel.trim()
					: "";
		alias = name || "(blank)";
		harness = null;
	}

	const model =
		typeof stage.model === "string" && stage.model.trim() && rawHarness !== ALIAS_HARNESS_ID
			? stage.model.trim()
			: typeof project?.defaultModel === "string" && project.defaultModel.trim()
				? project.defaultModel.trim()
				: "";

	const explicitTier = [stage.tier, task.tier, task.requiredTier].find((t) =>
		/^T[0-3]$/.test(String(t || "").trim()),
	);
	const tier = explicitTier
		? String(explicitTier).trim()
		: kind === "ci"
			? "T0"
			: runnableType
				? "T1"
				: "T0";

	const runnerless = kind === "ci" || kind === "merge";
	// Stage runnerPolicy (present only when the stage restricts Runners, so
	// unrestricted requirements keep their exact legacy shape).
	const runnerPolicy = normalizeStageRunnerPolicy(stage.runnerPolicy);
	return { harness: runnerless ? null : harness, model: runnerless ? "" : model, tier: runnerless && !explicitTier ? "T0" : tier, alias: runnerless ? null : alias, runnableType, hostCommand, kind, stageId: stage.id ?? null, ...(runnerPolicy ? { runnerPolicy } : {}) };
}

import { useEffect, useState } from 'react';
import { api } from '../../services/api';
import { normalizeStageRunnerPolicy } from '../../../../shared/stageRunnerPolicy.js';
import { runnerDisplayName, visibleRunners } from '../settings/runnerConfigHelpers';
import { InfoTooltip } from '../common/InfoTooltip';
import { SelectDropdown } from '../common/SelectDropdown';

const MODE_COPY = {
  off: 'Every Runner may take this stage.',
  allow: 'Only the selected Runners may take this stage.',
  block: 'Every Runner except the selected ones may take this stage.',
};

const loadRoster = async () => {
  const list = await api.getRunners();
  return Array.isArray(list) ? list : [];
};

/***
 * MARK: StageRunnerPolicyEditor
 * @description Runner allow/block list editor for stage settings. A mode
 *   selector (`Off` / `Only these runners` / `All except these runners`)
 *   plus a Runner checkbox roster fed by `GET /runners`. Writes through
 *   `onChange` as `{ mode, runners }`, or `undefined` when Off or when the
 *   selection is empty (empty always means unrestricted, so stored stages
 *   stay clean). Runner ids in the policy that no longer register stay in
 *   the list with an "unknown" badge — removing them is explicit, so a
 *   renamed Runner can never silently open a compliance gate.
 * @example <StageRunnerPolicyEditor value={stage.runnerPolicy} stageName="Publish" onChange={(p) => onUpdateStage(id, { runnerPolicy: p })} />
 * @param {Object} props
 * @param {Object} [props.value] - Current `stage.runnerPolicy` (or undefined when unrestricted).
 * @param {Array} [props.runners] - Runner records; when omitted the editor fetches `GET /runners` itself.
 * @param {string} [props.stageName] - Stage name for labels.
 * @param {string} [props.stageType] - Stage type (human stages show an unaffected note).
 * @param {Function} props.onChange - Called with the next policy or `undefined`.
 * @param {boolean} [props.disabled=false]
 ***/
export function StageRunnerPolicyEditor({
  value,
  runners,
  stageName = '',
  stageType = '',
  onChange,
  disabled = false,
}) {
  // Draft mode keeps the selector on allow/block while the selection is
  // empty (which writes undefined = unrestricted): without it the control
  // would snap back to Off before the first checkbox can be ticked. A
  // stored policy always wins over the draft.
  const [draftMode, setDraftMode] = useState(null);
  const [fetched, setFetched] = useState(null);
  const [loadFailed, setLoadFailed] = useState(false);
  const selfFetch = runners === undefined;

  useEffect(() => {
    if (!selfFetch) return undefined;
    let mounted = true;
    loadRoster().then(
      (list) => {
        if (mounted) setFetched(list);
      },
      () => {
        if (mounted) {
          setFetched([]);
          setLoadFailed(true);
        }
      }
    );
    return () => {
      mounted = false;
    };
  }, [selfFetch]);

  const loading = selfFetch ? fetched === null : runners === null;
  const roster = visibleRunners(selfFetch ? fetched : runners);
  const policy = normalizeStageRunnerPolicy(value);
  const selection = policy ? policy.runners : [];
  const mode = policy ? policy.mode : draftMode || 'off';

  const selectMode = (next) => {
    if (disabled) return;
    if (next === 'off') {
      setDraftMode(null);
      if (policy) onChange?.(undefined);
      return;
    }
    if (selection.length === 0) {
      setDraftMode(next);
      if (policy) onChange?.(undefined);
      return;
    }
    setDraftMode(null);
    onChange?.({ mode: next, runners: selection });
  };

  const toggleRunner = (runnerId, checked) => {
    if (disabled) return;
    const next = checked
      ? selection.includes(runnerId)
        ? selection
        : [...selection, runnerId]
      : selection.filter((id) => id !== runnerId);
    if (next.length === 0) {
      setDraftMode(mode === 'off' ? null : mode);
      onChange?.(undefined);
      return;
    }
    setDraftMode(null);
    onChange?.({ mode: mode === 'off' ? 'allow' : mode, runners: next });
  };

  const staleIds = selection.filter(
    (id) => !roster.some((r) => r && r.runnerId === id)
  );

  return (
    <div className="space-y-3 pt-2 border-t border-border-standard/60">
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <span className="text-[9px] font-bold uppercase text-text-muted tracking-wider block">
            Runner access:
          </span>
          <InfoTooltip
            title="Stage Runner Access"
            description="Restricts which Runners may take this stage: keep a publish step on one Runner, or a compliance scan onsite."
            behindTheScenes="Dispatch, direct claim, and merge leases all refuse Runners the stage does not allow"
            position="left"
          />
        </div>
        <SelectDropdown
          ariaLabel={`Runner access for ${stageName || 'stage'}`}
          className="block w-full"
          value={mode}
          onChange={selectMode}
          size="sm"
          options={[
            { value: 'off', label: 'Off (every Runner)' },
            { value: 'allow', label: 'Only these runners' },
            { value: 'block', label: 'All except these runners' },
          ]}
        />
        <p className="text-[10px] text-text-muted font-mono">{MODE_COPY[mode]}</p>
      </div>

      {mode !== 'off' && (
        <div className="space-y-1">
          {loading ? (
            <p className="text-[11px] text-text-muted">Loading runners…</p>
          ) : loadFailed ? (
            <p className="text-[11px] text-text-muted" role="alert">
              Could not load the Runner roster — the saved list below is unchanged.
            </p>
          ) : roster.length === 0 && staleIds.length === 0 ? (
            <p className="text-[11px] text-text-muted">No Runners have registered yet.</p>
          ) : (
            <div
              role="group"
              aria-label={`Runners for ${stageName || 'stage'}`}
              className="flex flex-col gap-1.5 max-h-[160px] overflow-y-auto custom-scrollbar p-1.5 bg-surface-container border border-border-standard rounded-sm"
            >
              {roster.map((runner) => {
                const id = runner?.runnerId;
                if (typeof id !== 'string' || !id) return null;
                const name = runnerDisplayName(runner) || id;
                const statusNote =
                  runner?.paused === true
                    ? 'paused'
                    : runner?.status && runner.status !== 'active'
                      ? runner.status
                      : '';
                return (
                  <label
                    key={id}
                    className="flex items-center gap-2 cursor-pointer select-none text-[11px] text-on-surface"
                  >
                    <input
                      type="checkbox"
                      checked={selection.includes(id)}
                      onChange={(e) => toggleRunner(id, e.target.checked)}
                      disabled={disabled}
                      aria-label={`${mode === 'allow' ? 'Allow' : 'Block'} runner ${name}`}
                      className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"
                    />
                    <span className="font-mono truncate">{name}</span>
                    {name !== id && (
                      <span className="font-mono text-text-muted truncate">{id}</span>
                    )}
                    {statusNote && (
                      <span className="text-[10px] font-mono text-text-muted">
                        ({statusNote})
                      </span>
                    )}
                  </label>
                );
              })}
              {staleIds.map((id) => (
                <label
                  key={`stale-${id}`}
                  className="flex items-center gap-2 cursor-pointer select-none text-[11px] text-on-surface"
                >
                  <input
                    type="checkbox"
                    checked
                    onChange={(e) => toggleRunner(id, e.target.checked)}
                    disabled={disabled}
                    aria-label={`Remove unknown runner ${id}`}
                    className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"
                  />
                  <span className="font-mono truncate">{id}</span>
                  <span className="text-[9px] font-mono uppercase tracking-wider px-1 py-px rounded-sm bg-amber-500/15 text-amber-300 border border-amber-500/30">
                    unknown
                  </span>
                </label>
              ))}
            </div>
          )}
          {selection.length === 0 && !loading && (
            <p className="text-[10px] text-text-muted font-mono">
              No runners selected — every Runner may take this stage until you select one.
            </p>
          )}
        </div>
      )}

      {String(stageType).toLowerCase() === 'human' && (
        <p className="text-[10px] text-text-muted font-mono">
          Human stages run no Runner work, so this list does not affect them.
        </p>
      )}
    </div>
  );
}

import { config } from "../config.js";
import { applyRunnerReport } from "./execution/applyRunnerReport.js";
import { applyIntegrationReport } from "./execution/applyIntegrationReport.js";
import { normalizeStageType } from "../projectStore.js";
import { git, defaultBranch } from "../git.js";
import { circuitSnapshot, isTripped } from "./circuitBreaker.js";
import { scanClaimableTasks } from "./dispatch/scanClaimableTasks.js";
import { resolveAliasRequirement } from "./dispatch/resolveAliasRequirement.js";
import { runnerMatches } from "./dispatch/runnerMatches.js";
import { operatorConfigVerdict } from "./dispatch/operatorConfigVerdict.js";
import { stageRunnerPolicyVerdict } from "../../shared/stageRunnerPolicy.js";
import { taskRequirements } from "./dispatch/taskRequirements.js";
import { curateRunnerPrompt } from "./curateRunnerPrompt.js";
import { materializeRunnerTaskDocs } from "./execution/materializeRunnerTaskDocs.js";
import { buildCommandKeywordContext, expandStageCommand } from "./commandStages.js";
import { resolveStagesForTask } from "./stageResolution.js";
import { emitStageLifecycle } from "./stageLifecycle.js";
import {
	resolveStageLabel,
	resolveStageTimeout,
	runnerStageTimeoutStatus,
} from "./stagePolicy.js";
import { redactSecretsText } from "../../shared/redactSecrets.js";
import { buildBelowMinimumRefusal } from "./runnerVersionCompat.js";
import { servingModelFor } from "./runnerPosture.js";
import {
	buildTimelineAttribution,
	stampArrivalRowAttribution,
} from "./runAttribution.js";

/***
 * MARK: resolveCiTimeoutMs
 * @description CI budget for one dispatched stage, in milliseconds. Honors
 *   the stage's explicit `timeoutMs`, then the legacy `timeout` field the
 *   project file actually carries, then the project default, then the
 *   10-minute floor. The `timeout` fallback matters: without it the
 *   Automated-tests stage's configured 3600000ms never reached the runner
 *   and every gate longer than 10 minutes was SIGKILLed mid-run (task
 *   b5716327: green suites reported as "exit code 1").
 * @example resolveCiTimeoutMs({ timeout: 3600000 }, {}) => 3600000
 * @param {Object} [resolved] - resolved CI stage definition.
 * @param {Object} [project] - project record (optional `ciTimeoutMs`).
 * @returns {number} Effective CI timeout in milliseconds.
 ***/
export const resolveCiTimeoutMs = (resolved, project) => {
	return (
		Number(resolved?.timeoutMs) ||
		Number(resolved?.timeout) ||
		Number(project?.ciTimeoutMs) ||
		600000
	);
};

/***
 * MARK: stampDispatchRunAttribution
 * @description Stamps one dispatched run's resolved choice onto the task —
 *   the runner-side mirror of the embedded dispatch stamp in
 *   `executeStage`, so timeline rows and reports attribute the model that
 *   was ACTUALLY matched, never a fallback. The requirement's harness/
 *   model name the run (model normalized through `servingModelFor`, so the
 *   "default" sentinel and non-LLM kinds never stamp); a resolved alias
 *   rides along with its name and target index. CI/merge requirements carry
 *   no harness/model, so nothing is stamped and their rows stay blank — a
 *   scripted stage must never show a model. Best-effort: a stamping failure
 *   never blocks the claim.
 * @example stampDispatchRunAttribution({ taskStore, project, task, stage, stages, req: { harness: 'pi', model: 'm', kind: 'agent' } })
 * @param {Object} args - `{ taskStore, project, task, stage, stages, req }`.
 * @returns {Object|null} The stamped attribution, or null when nothing ran behind the dispatch.
 ***/
export function stampDispatchRunAttribution({ taskStore, project, task, stage, stages, req }) {
	try {
		if (!task || !req) return null;
		const resolvedAlias =
			req.alias && typeof req.alias === "object" && typeof req.alias.name === "string"
				? req.alias
				: null;
		const attribution = buildTimelineAttribution({
			harnessId: typeof req.harness === "string" && req.harness.trim() ? req.harness.trim() : null,
			modelRef: servingModelFor({ kind: req.kind, model: req.model }),
			aliasName: resolvedAlias ? resolvedAlias.name : null,
			targetIndex: resolvedAlias ? resolvedAlias.targetIndex : null,
		});
		if (!attribution) return null;
		task.currentRunAttribution = {
			stageId: stage?.id ?? task.currentStageId ?? null,
			...attribution,
		};
		const arrivalLabel =
			stage?.name || resolveStageLabel(stage?.id ?? task.currentStageId, stages || []);
		const stampedRow = stampArrivalRowAttribution(task, arrivalLabel, attribution);
		if (stampedRow) {
			try {
				taskStore?._saveTaskMarkdown?.(project?.cwd, task);
			} catch {
				// Persisting the stamp is best-effort; the in-memory
				// attribution already drives the completion row.
			}
		}
		return attribution;
	} catch {
		return null;
	}
}

/***
 * MARK: prepareIntegrationAttempt
 * @description Backend-side preparation for one leased `integrate` dispatch
 *   (Step 4): fetches the origin (read-only — the backend never pushes),
 *   reads the remote task-branch and target-branch tips as the attempt's
 *   expected SHAs, and pins a stable `mergeAttemptId` on the task so every
 *   dispatch poll for this merge reuses one queue entry (idempotent
 *   re-enqueue) instead of queueing a duplicate merge per poll. Throws
 *   `INTEGRATION_UNPREPARED` when the refs cannot be read (no origin ref
 *   yet, fetch failure) — the task stays `in_stage` for the next poll.
 * @example await prepareIntegrationAttempt({ taskStore, projectStore, projectId: 'p', task }) => { targetBranch: 'main', ... }
 * @param {Object} args - `{ taskStore, projectStore, projectId, task }`.
 * @returns {Promise<Object>} `{ targetBranch, taskBranch, expectedTaskSha, expectedTargetSha, mergeAttemptId }`.
 ***/
export const prepareIntegrationAttempt = async ({ taskStore, projectStore, projectId, task }) => {
	const unprepared = (detail) => {
		const err = new Error(`Integration attempt unprepared: ${detail}`);
		err.code = "INTEGRATION_UNPREPARED";
		throw err;
	};
	const project = projectStore?.getProject?.(projectId);
	const cwd = project?.cwd;
	if (!cwd) unprepared("project has no checkout");
	const taskBranch = taskStore.resolveTaskBranch(task);
	let targetBranch;
	try {
		targetBranch = await defaultBranch(cwd);
	} catch {
		unprepared("cannot resolve the target branch");
	}
	try {
		// Prune: a deleted remote task branch must vanish from the
		// remote-tracking refs too, or a later attempt would merge a
		// resurrected stale tip.
		await git(cwd, ["fetch", "--prune", "origin"], { timeout: 60000 });
	} catch (e) {
		unprepared(`fetch failed (${e?.message || e})`);
	}
	const readRef = async (ref) => {
		try {
			return (await git(cwd, ["rev-parse", "--verify", ref])).stdout.trim() || null;
		} catch {
			return null;
		}
	};
	const expectedTargetSha = await readRef(`origin/${targetBranch}`);
	const expectedTaskSha = await readRef(`origin/${taskBranch}`);
	if (!expectedTargetSha) unprepared(`remote ref 'origin/${targetBranch}' does not exist`);
	if (!expectedTaskSha) unprepared(`remote ref 'origin/${taskBranch}' does not exist (task work not pushed yet)`);
	// A retry after a failed attempt gets a FRESH attempt id: the failed
	// lease settled terminal (landed/conflict/stale-head/failed) in the
	// integration queue, and re-enqueueing the same id would collide with
	// that settled entry instead of queueing a re-based merge.
	const failedBefore = !!(task.lastError && (task.lastError.message || task.lastError.reason || task.lastError.stageId || task.lastError.stderr));
	let mergeAttemptId = `merge-${String(task.id).slice(0, 8)}-${Date.now()}`;
	if (typeof task.mergeAttemptId === "string" && task.mergeAttemptId.trim() && !failedBefore) {
		mergeAttemptId = task.mergeAttemptId.trim();
	} else {
		taskStore.updateTask(projectId, task.id, { mergeAttemptId }, cwd);
		task.mergeAttemptId = mergeAttemptId;
	}
	return { targetBranch, taskBranch, expectedTaskSha, expectedTargetSha, mergeAttemptId };
};

/***
 * MARK: registerRunnerRoutes
 * @description Runner-facing endpoints (ADR 0009 lifecycle steps 1–6): join
 *   registration, heartbeat, the operator approve/deny/revoke/pause/resume
 *   + list surface the Phase 2 onboarding UI drives, the atomic task-claim
 *   route backed by ClaimStore (200 + lease or 409 + holder), and the
 *   execution-report endpoints (progress, logs, complete-execution with
 *   engine-owned finish, interrupt, monitor). Credential
 *   scope is enforced per request: the claim's Runner always comes from
 *   the authenticated credential, never from the body (R04 wrong-scope).
 * @example await app.register(runnerRoutes, { deps })
 ***/
export const registerRunnerRoutes = async (app, { deps }) => {
	const {
		runnerRegistry,
		claimStore,
		steerStore,
		executionLedger,
		integrationQueue,
		taskStore,
		projectStore,
		resolveAndGuardProject,
		eventBridge,
	} = deps;

	const sendStoreError = (reply, err) => {
		const status = err.statusCode || 500;
		const body = { error: err.message || "Internal error" };
		if (err.code) body.code = err.code;
		if (err.holder) body.holder = err.holder;
		return reply.status(status).send(body);
	};

	const ciPayloadFor = async (projectId, task, stage) => {
		const project = projectStore.getProject(projectId);
		const stages = resolveStagesForTask(project, task);
		// A null/undefined stage (e.g. the single-assignment claim route) falls
		// back to the task's current stage — dropping the payload here would
		// silently strip kind/command/runOnBranch and the Runner would run the
		// command in the task worktree regardless of the stage's branch mode.
		const resolved = stage || stages.find((x) => String(x?.id) === String(task?.currentStageId)) || stages[0];
		if (!resolved) return {};
		const type = String(resolved.type || "").toLowerCase();
		if (!["ci", "script", "deploy", "command"].includes(type)) return {};
		// Branch mode rides every payload — including the error fallback — so a
		// Runner can never silently degrade a 'primary'/'custom' stage back to
		// the task worktree (which is exactly how publish stages used to fail:
		// deploy.sh refuses to run from a kb/* worktree).
		const runOnBranch = typeof resolved.runOnBranch === "string" ? resolved.runOnBranch : "task";
		const branchPayload = {
			runOnBranch,
			...(runOnBranch === "custom" && typeof resolved.customBranch === "string" && resolved.customBranch.trim()
				? { customBranch: resolved.customBranch.trim() }
				: {}),
		};
		// Generic lifecycle seam (mirrors runCommandStage): every command
		// stage announces entry the same way, whether a Runner or the
		// backend executes it. Installed continuity plugins may record
		// entry markers and contribute child-process environment here;
		// with no plugins this is an empty bag. Never throws: a plugin
		// failure must not break dispatch.
		let lifecycleEnv = {};
		try {
			const lifecycle = await emitStageLifecycle("stage:enter", {
				store: taskStore,
				projectId,
				taskId: task?.id,
				stage: resolved,
				kind: "ci",
				cwd: project?.cwd || "",
			});
			if (lifecycle && typeof lifecycle.env === "object") {
				lifecycleEnv = lifecycle.env;
			}
		} catch {
			lifecycleEnv = {};
		}
		try {
			const ctx = buildCommandKeywordContext({ task, stage: resolved, project, projectCwd: project?.cwd || "" });
			return {
				kind: "ci",
				command: expandStageCommand(resolved.command || resolved.script || "echo 'CI stage completed'", ctx),
				timeoutMs: resolveCiTimeoutMs(resolved, project),
				...branchPayload,
				env: lifecycleEnv,
			};
		} catch { return { kind: "ci", command: resolved.command || resolved.script || "", timeoutMs: 600000, ...branchPayload, env: lifecycleEnv }; }
	};

	const authedRunner = (request) => {
		const credential = String(
			request.headers?.["x-runner-credential"] || "",
		).trim();
		return runnerRegistry.authenticate(credential);
	};

	app.post("/runners/register", async (request, reply) => {
		try {
			const result = runnerRegistry.register({
				runnerId: request.body?.runnerId,
				joinToken: request.body?.joinToken,
				facts: request.body?.facts || {},
			});
			return reply.status(result.status === "pending" ? 202 : 200).send(result);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/heartbeat", async (request, reply) => {
		try {
			const runner = authedRunner(request);
			const result = runnerRegistry.heartbeat({
				runnerId: request.body?.runnerId || runner.runnerId,
				credential: String(
					request.headers?.["x-runner-credential"] || "",
				).trim(),
				facts: request.body?.facts || {},
				// G11 audit alert: one identity from multiple origins.
				origin: request.ip || null,
			});
			// D5 pull channel (ADR 0011): pending steers for this
			// Runner's live executions ride the heartbeat response, so
			// steering needs no second channel. Stale Runner, live
			// lease: the steer waits here until the TTL lapses.
			const pendingSteers = [];
			for (const hold of claimStore.liveHolds()) {
				if (hold.runnerId !== runner.runnerId) continue;
				for (const steer of steerStore.pendingFor(hold.executionId)) {
					pendingSteers.push({
						steerId: steer.steerId,
						taskId: hold.taskId,
						projectId: hold.projectId,
						executionId: hold.executionId,
						epoch: hold.epoch,
						text: steer.text,
					});
				}
			}
			return { ...result, pendingSteers };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners", async () => {
		return runnerRegistry.list();
	});

	app.post("/runners/:id/approve", async (request, reply) => {
		try {
			return runnerRegistry.approve(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/rotate", async (request, reply) => {
		try {
			return runnerRegistry.rotate(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/deny", async (request, reply) => {
		try {
			return runnerRegistry.deny(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/revoke", async (request, reply) => {
		try {
			return runnerRegistry.revoke(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/pause", async (request, reply) => {
		try {
			return runnerRegistry.pause(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/resume", async (request, reply) => {
		try {
			return runnerRegistry.resume(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners/:id/config", async (request, reply) => {
		// Operator-owned Runner configuration for the System Settings
		// Runner screen (display name, tool filter, job-type switches,
		// directories, project override). No Runner credential needed:
		// same operator surface as approve/deny/pause/resume.
		try {
			return runnerRegistry.getConfig(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.patch("/runners/:id/config", async (request, reply) => {
		try {
			return runnerRegistry.updateConfig(request.params.id, request.body || {});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/skip", async (request, reply) => {
		// Operator skip: advance the task this Runner currently holds past
		// its stage and release the lease, so the in-flight Runner report
		// lands stale (stage-moved) instead of re-advancing. Same operator
		// surface as pause/resume — no Runner credential needed. 404 when
		// the Runner is unknown or holds nothing; 409 when its task is
		// already on the last stage.
		try {
			const runnerId = request.params.id;
			const record = runnerRegistry
				.records()
				.find((r) => r && r.runnerId === runnerId);
			if (!record) {
				return reply
					.status(404)
					.send({ error: `Unknown Runner ${runnerId}.`, code: "UNKNOWN_RUNNER" });
			}
			const hold = claimStore
				.liveHolds()
				.find((h) => h && h.runnerId === runnerId);
			if (!hold) {
				return reply.status(404).send({
					error: `Runner ${runnerId} has no active task to skip.`,
					code: "NOTHING_TO_SKIP",
				});
			}
			const project = projectStore.getProject(hold.projectId);
			const task = taskStore.getTask(hold.projectId, hold.taskId);
			if (!task) {
				claimStore.invalidate(hold.taskId);
				return reply.status(404).send({
					error: "Held task not found.",
					code: "NOTHING_TO_SKIP",
				});
			}
			const stages = Array.isArray(project?.stages) ? project.stages : [];
			const index = stages.findIndex((s) => s && s.id === task.currentStageId);
			if (index === -1 || index >= stages.length - 1) {
				return reply.status(409).send({
					error: `Task ${hold.taskId} is already on the last stage.`,
					code: "NOTHING_TO_SKIP",
				});
			}
			const next = stages[index + 1];
			taskStore.updateTask(
				hold.projectId,
				hold.taskId,
				{ currentStageId: next.id },
				project?.cwd,
			);
			claimStore.invalidate(hold.taskId);
			return {
				success: true,
				runnerId,
				taskId: hold.taskId,
				from: task.currentStageId,
				to: next.id,
			};
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	const guardedTask = (request, reply) => {
		const projectId = resolveAndGuardProject(
			request.body?.projectId || request.query?.projectId,
			reply,
		);
		if (!projectId) return null;
		const task = taskStore.getTask(projectId, request.params.id);
		if (!task) {
			reply.status(404).send({ error: "Task not found" });
			return null;
		}
		return { projectId, task };
	};

	app.get("/runners/monitor", async () => {
		// Multi-Runner UI (WP-3.4): who runs what right now, so
		// Settings › Runners can show live assignments.
		// `scheduler` exposes the cutover deferral counters so a task
		// sitting in_stage is diagnosable: a climbing `deferredDispatch`
		// with no Runner pickup means the fleet is empty or mismatched.
		const liveAssignments = claimStore.liveHolds().map((hold) => {
			const record = runnerRegistry.records().find((r) => r.runnerId === hold.runnerId) || null;
			return {
				runnerId: hold.runnerId,
				projectId: hold.projectId,
				taskId: hold.taskId,
				executionId: hold.executionId,
				epoch: hold.epoch,
				startedAt: hold.startedAt ?? null,
				stageId: executionLedger.stageFor(hold.executionId),
				prompt: executionLedger.promptFor(hold.executionId),
				serving: executionLedger.servingFor(hold.executionId),
				lastSeenAt: record?.lastSeenAt ?? null,
			};
		});
		const sched = taskStore.schedulerStats || {};
		const scheduler = {
			ticks: sched.ticks || 0,
			dispatched: sched.dispatched || 0,
			deferredDispatch: sched.deferredDispatch || 0,
			deferredTripped: sched.deferredTripped || 0,
			lastOutcome: sched.lastOutcome ?? null,
			lastDispatchAt: sched.lastDispatchAt ?? null,
		};
		// Step 6: surface integration-queue health (depth/lease per scope
		// via GET /runners/integration; global lease counters here) so a
		// stuck merge queue is visible before tasks pile up behind it.
		const integration = integrationQueue ? integrationQueue.snapshot() : {};
		return { ...executionLedger.snapshot(), liveAssignments, scheduler, integration };
	});

	app.post("/tasks/:id/progress", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.recordProgress({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				stageId: request.body?.stageId,
				event: request.body?.event,
				prompt: request.body?.prompt ?? null,
				harness: request.body?.harness ?? null,
				model: request.body?.model ?? null,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/logs", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const receipt = executionLedger.ingestLogs({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				seq: request.body?.seq,
				bytes: request.body?.bytes,
			});
			// Live turn-by-turn stream: fan the ingested frame out over the
			// socket so the Logs tab shows Runner output as it happens, not
			// only after the next task refetch. Fire-and-forget: a dead
			// socket must never fail the ingest. Duplicates are suppressed
			// once the stored entry arrives (client dedupes on
			// executionId+seq), and duplicate/old frames are never emitted.
			// The broadcast is redacted even though the stored copy already
			// is: legacy text frames reach this route unredacted from older
			// Runners (the fallback text path), and the live socket must
			// never carry secrets even for one frame.
			if (!receipt.duplicate) {
				eventBridge
					?.emitProcessEvent(ctx.projectId, "process:stdout", {
						taskId: request.params.id,
						projectId: ctx.projectId,
						chunk: `[runner ${runner.runnerId}] ${redactSecretsText(String(request.body?.bytes ?? ""))}`,
						tag: "[RUNNER]",
						runnerId: runner.runnerId,
						executionId: request.body?.executionId,
						seq: request.body?.seq,
					})
					?.catch?.(() => {});
			}
			return receipt;
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/log-events", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const receipt = executionLedger.ingestLogEvents({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				seq: request.body?.seq,
				events: request.body?.events,
			});
			// Live structured stream: fan the ingested entries out over the
			// socket so the Logs tab renders tool calls, results, thinking,
			// errors, and telemetry as they happen — the same records a
			// later refetch persists. Only the entries appended by THIS
			// batch ship (re-read from the stored tail, which the ledger
			// just extended). Fire-and-forget; duplicates never emit.
			if (!receipt.duplicate) {
				const task = taskStore.getTask(ctx.projectId, request.params.id);
				const stored = Array.isArray(task?.logEntries) ? task.logEntries : [];
				const fresh = stored
					.filter(
						(entry) =>
							entry?.meta?.executionId === request.body?.executionId &&
							entry?.meta?.seq === request.body?.seq &&
							entry?.meta?.source === "runner-structured",
					)
					.slice(-200);
				eventBridge
					?.emitProcessEvent(ctx.projectId, "process:log-entries", {
						taskId: request.params.id,
						projectId: ctx.projectId,
						entries: fresh,
						runnerId: runner.runnerId,
						executionId: request.body?.executionId,
						seq: request.body?.seq,
					})
					?.catch?.(() => {});
			}
			return receipt;
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/verify-sha", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.noteRemoteVerification({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				sha: request.body?.sha ?? null,
				present: request.body?.present,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/complete-execution", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const receipt = await executionLedger.completeExecution({
				claimStore,
				taskStore,
				projectStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				sha: request.body?.sha ?? null,
				branch: request.body?.branch ?? null,
				posture: request.body?.posture ?? null,
			});
			if (receipt.duplicate) return receipt;
			// Engine-owned finish: the lease fence accepted the report, so
			// the backend now applies the same transitions as the embedded
			// path (report, survey park, failure routing, advance). The
			// task must still be live and on the reported stage; anything
			// else keeps the accepted report but skips the finish.
			const live = taskStore.getTask(ctx.projectId, request.params.id);
			const terminal = ["complete", "failed"].includes(
				String(live?.status).toLowerCase(),
			);
			if (terminal) {
				return { ...receipt, advanced: false, reason: "task-terminal" };
			}
			const runStage = receipt.reportedStage ?? live?.currentStageId ?? null;
			if (runStage && live?.currentStageId && runStage !== live.currentStageId) {
				return { ...receipt, advanced: false, reason: "stage-moved" };
			}
			const outcome = request.body?.outcome ?? "passed";
			if (outcome !== "passed" && outcome !== "failed") {
				return reply.status(400).send({
					error: "outcome must be passed or failed",
					code: "INVALID_OUTCOME",
				});
			}
			// Runner-authored task files (plan/survey) land in the backend
			// task folder BEFORE the finish advances the task, so a following
			// backend-run CI stage reading {{taskDocs}} can see them.
			materializeRunnerTaskDocs({
				project: projectStore.getProject(ctx.projectId),
				taskId: request.params.id,
				files: request.body?.taskFiles,
			});
			const harnessId =
				runner.facts?.harnesses?.[0]?.id || request.body?.harnessId || "unknown";
			// Runner-run integration: the merge already landed via the
			// leased CAS push — verify read-only, freeze the baseline,
			// and advance. Never the generic stage finish.
			const project = projectStore.getProject(ctx.projectId);
			const allStages = resolveStagesForTask(project, live);
			const currentStage =
				allStages.find((s) => String(s?.id) === String(live?.currentStageId)) || allStages[0] || {};
			if (
				normalizeStageType(currentStage.type) === "merge" &&
				request.body?.integration?.outcome === "landed"
			) {
				const finish = await applyIntegrationReport({
					store: taskStore,
					projectStore,
					projectId: ctx.projectId,
					taskId: request.params.id,
					stage: currentStage,
					stages: allStages,
					integration: request.body.integration,
					runnerId: runner.runnerId,
				});
				return { ...receipt, ...finish };
			}
			// The Runner's explicit served-model field (new runners); normalized
			// through servingModelFor with the stage's kind so CI stages and the
			// "default" sentinel can never land in the report. Old runners omit
			// the field and applyRunnerReport falls back to the dispatch stamp.
			const reportedModelRef = servingModelFor({
				kind: normalizeStageType(currentStage.type),
				model: request.body?.model ?? null,
			});
			const finish = await applyRunnerReport({
				store: taskStore,
				projectStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				outcome: {
					status: outcome,
					output: request.body?.output ?? "",
					summary: request.body?.summary ?? "",
					modifiedFiles: request.body?.modifiedFiles ?? [],
					harnessId,
					modelRef: reportedModelRef,
					failureKind: request.body?.failureKind ?? null,
					failureReason: request.body?.failureReason ?? null,
					duration: request.body?.durationMs
						? String(Number(request.body.durationMs) / 1000)
						: "0.0",
					runnerId: runner.runnerId,
				},
			});
			return { ...receipt, ...finish };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/interrupt", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.interruptExecution({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId ?? null,
				reason: request.body?.reason ?? null,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/claim", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const claimedRunnerId = request.body?.runnerId;
		if (
			claimedRunnerId &&
			claimedRunnerId !== runner.runnerId
		) {
			return reply.status(403).send({
				error: "Credential does not belong to the claimed Runner.",
				code: "SCOPE_MISMATCH",
			});
		}
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		// Runner self-update floor (Option A, ADR 0012): a known product
		// version below KAINBAIN_RUNNER_MIN_VERSION is refused so it cannot
		// mis-execute — the daemon self-updates on this code and retries.
		const belowMinimum = buildBelowMinimumRefusal({ runner, minVersion: config.runnerMinVersion });
		if (belowMinimum) return reply.status(409).send(belowMinimum);
		const projectId = resolveAndGuardProject(
			request.body?.projectId || request.query?.projectId,
			reply,
		);
		if (!projectId) return;
		const task = taskStore.getTask(projectId, request.params.id);
		if (!task) return reply.status(404).send({ error: "Task not found" });
		// Operator settings (System Settings › Runners) bind this direct
		// claim exactly like the dispatch scan: a Runner whose project is
		// unloaded, whose job-type switch is off, or whose tool subset
		// excludes the stage harness must not claim the task by asking for
		// it directly. Fail loud (409 + the verdict code) instead of
		// silently honouring a claim the operator switched off.
		const req = taskRequirements(projectStore.getProject(projectId) || {}, task);
		const claimVerdict = operatorConfigVerdict(runner, req, { projectId });
		if (!claimVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} settings refuse this task (${claimVerdict.reason}).`,
				code: claimVerdict.reason,
			});
		}
		// Stage runnerPolicy (stage settings allow/block list) binds this
		// direct claim exactly like the dispatch scan: claiming by task id
		// must not bypass a stage the Runner is not allowed on.
		const claimPolicyVerdict = stageRunnerPolicyVerdict(req.runnerPolicy, runner.runnerId);
		if (!claimPolicyVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is refused by this stage's Runner list (${claimPolicyVerdict.reason}).`,
				code: claimPolicyVerdict.reason,
			});
		}
		try {
			const { executionId, epoch } = claimStore.claim(
				request.params.id,
				runner.runnerId,
				projectId,
			);
			// Same run attribution as the dispatch path: the requirement's
			// resolved harness/model names this run on the timeline/reports.
			const project = projectStore.getProject(projectId);
			const stages = resolveStagesForTask(project, task);
			const stage =
				stages.find((s) => String(s?.id) === String(task.currentStageId)) || stages[0] || null;
			stampDispatchRunAttribution({ taskStore, project, task, stage, stages, req });
			return { taskId: request.params.id, runnerId: runner.runnerId, executionId, epoch, ...await ciPayloadFor(projectId, task, null), prompt: curateRunnerPrompt({ project, task, stageId: task.currentStageId }) };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/claim-heartbeat", async (request, reply) => {
		// Lease renewal for long Runner executions (D1): the claim TTL
		// bounds a dead Runner's hold, so a live Runner must extend it
		// while the harness runs — otherwise the hold lapses mid-stage,
		// the task re-queues, and the finisher reports STALE_EPOCH.
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const hold = claimStore.describe(request.params.id);
			if (!hold || hold.runnerId !== runner.runnerId) {
				const err = new Error(
					`Stale execution for task ${request.params.id}: lease belongs to another Runner.`,
				);
				err.statusCode = 409;
				err.code = "STALE_EPOCH";
				throw err;
			}
			// Wall-clock stage timeout (no infinite renewal): a live Runner
			// renewing its lease forever must not outrun the stage budget —
			// otherwise a stuck harness sits claimed indefinitely and the
			// task reads frozen. On breach the hold is released and the
			// stage fails through the normal failure routing (retry/failback),
			// so the task re-queues instead of stranding.
			const project = projectStore.getProject(ctx.projectId);
			const stages = resolveStagesForTask(project, ctx.task);
			const stage =
				stages.find(
					(s) => String(s?.id) === String(ctx.task?.currentStageId),
				) || null;
			const timeoutMs = resolveStageTimeout(
				stage,
				stage?.type,
				config,
				project,
			);
			const { timedOut, elapsedMs } = runnerStageTimeoutStatus({
				startedAt: hold.startedAt ?? null,
				timeoutMs,
			});
			if (timedOut) {
				claimStore.invalidate(request.params.id);
				const reason =
					`Stage timed out after ${elapsedMs}ms (budget ${timeoutMs}ms) ` +
					`on stage '${stage?.name || stage?.id || ctx.task?.currentStageId}'.`;
				try {
					await applyRunnerReport({
						store: taskStore,
						projectStore,
						projectId: ctx.projectId,
						taskId: request.params.id,
						outcome: {
							status: "failed",
							output: "",
							harnessId: runner.facts?.harnesses?.[0]?.id || "unknown",
							failureKind: "timeout",
							failureReason: reason,
							duration: String(elapsedMs / 1000),
							runnerId: runner.runnerId,
						},
					});
				} catch {
					// The 409 below is the contract; a reporting failure must
					// never mask it (the zombie's late finish stays stale).
				}
				return reply.status(409).send({
					error: reason,
					code: "STAGE_TIMEOUT",
					timeoutMs,
					elapsedMs,
				});
			}
			const { epoch } = claimStore.heartbeat(
				request.params.id,
				request.body?.executionId,
			);
			return { taskId: request.params.id, runnerId: runner.runnerId, epoch };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/dispatch", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!runnerRegistry.isFresh(runner)) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is stale — heartbeat, then ask again`,
				code: "STALE_RUNNER",
			});
		}
		// Parked Runners keep heartbeating (freshness is liveness, not
		// eligibility) but take no new work: fail fast here as well as in
		// the per-candidate match, so a paused fleet reads as paused and
		// not "no capable match".
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		// Runner self-update floor (Option A, ADR 0012): same refusal as
		// direct claim — shared helper so the two gates cannot drift.
		const belowMinimum = buildBelowMinimumRefusal({ runner, minVersion: config.runnerMinVersion });
		if (belowMinimum) return reply.status(409).send(belowMinimum);
		if (isTripped(taskStore)) {
			const circuit = circuitSnapshot(taskStore);
			return reply.status(409).send({
				error: "Engine is tripped — dispatch is stopped",
				tripped: true,
				reason: circuit.reason,
				source: circuit.source,
				trippedAt: circuit.trippedAt,
			});
		}
		const projectIds = Array.isArray(request.body?.projectIds)
			? request.body.projectIds
			: undefined;
		runnerRegistry.recordDispatchScope(runner.runnerId, projectIds);
		// D8 burn control (ADR 0010): the fleet cap stops parallel burn
		// before any scan; per-project caps skip that project's candidates
		// below. 0 disables that cap (default: single-Runner behaviour).
		const fleetCap = config.runnerMaxConcurrentFleet || 0;
		if (fleetCap > 0 && claimStore.countLiveHolds() >= fleetCap) {
			return reply.status(429).send({
				error: `Fleet at Runner concurrency cap (${fleetCap}); backing off.`,
				code: "FLEET_CONCURRENCY_EXHAUSTED",
			});
		}
		const projectCap = config.runnerMaxConcurrentPerProject || 0;
		const candidates = scanClaimableTasks(
			{ projectStore, taskStore, claimStore },
			{ projectIds, maxWaitMs: config.dispatchMaxWaitMs || 0 },
		);
		if (candidates.length === 0) {
			return { assigned: false, code: "NO_CLAIMABLE_TASKS" };
		}
		// A harness is dispatch-servable when some active, fresh Runner
		// advertises it. Alias targets on unserved harnesses are skipped
		// for this resolution (share redistributes, per the alias
		// contract); nothing served at all resolves null → loud miss.
		const isHarnessKnown = (name) =>
			runnerRegistry.records().some(
				(rec) =>
					rec?.status === "active" &&
					rec?.paused !== true &&
					runnerRegistry.isFresh(rec) &&
					(rec.capabilities?.harnesses || []).some((h) => h?.id === name),
			);
		const misses = {};
		for (const cand of candidates) {
			let req = cand.req;
			if (cand.req.alias) {
				const resolved = resolveAliasRequirement({
					project: projectStore.getProject(cand.projectId),
					aliasName: cand.req.alias,
					isHarnessKnown,
				});
				if (!resolved) {
					misses.ALIAS_UNRESOLVED = (misses.ALIAS_UNRESOLVED || 0) + 1;
					continue;
				}
				req = {
					...cand.req,
					harness: resolved.harness,
					model: resolved.model,
					alias: { name: resolved.aliasName, targetIndex: resolved.targetIndex },
				};
			}
			// The candidate's project travels alongside the requirements so
			// the operator project-scope check in `runnerMatches` can
			// refuse out-of-scope projects loudly (PROJECT_SCOPE) instead
			// of dispatching work the operator unloaded for this Runner.
			const verdict = runnerMatches(runner, req, {
				staleAfterMs: runnerRegistry.staleAfterMs,
				projectId: cand.projectId,
			});
			if (!verdict.ok) {
				misses[verdict.reason] = (misses[verdict.reason] || 0) + 1;
				continue;
			}
			if (
				projectCap > 0 &&
				claimStore.countLiveHolds({ projectId: cand.projectId }) >= projectCap
			) {
				misses.PROJECT_BUSY = (misses.PROJECT_BUSY || 0) + 1;
				continue;
			}
			// Merge stages dispatch as leased `integrate` jobs (Step 4): the
			// task claim fences progress/logs/completion exactly like any
			// stage, while the integration lease serializes target-branch
			// writes. A busy integration slot backs the Runner off to poll
			// again (the request stays queued — never lost, never doubled).
			if (req.kind === "merge") {
				let attempt;
				try {
					attempt = await prepareIntegrationAttempt({
						taskStore,
						projectStore,
						projectId: cand.projectId,
						task: cand.task,
					});
				} catch (err) {
					if (err?.code === "INTEGRATION_UNPREPARED") {
						misses.INTEGRATION_UNPREPARED = (misses.INTEGRATION_UNPREPARED || 0) + 1;
						continue;
					}
					return sendStoreError(reply, err);
				}
				let executionId;
				let epoch;
				try {
					({ executionId, epoch } = claimStore.claim(cand.taskId, runner.runnerId, cand.projectId));
				} catch (err) {
					if (err?.code === "CLAIM_CONFLICT") continue;
					return sendStoreError(reply, err);
				}
				if (!integrationQueue) {
					claimStore.invalidate(cand.taskId);
					misses.NO_INTEGRATION_QUEUE = (misses.NO_INTEGRATION_QUEUE || 0) + 1;
					continue;
				}
				integrationQueue.enqueue({
					projectId: cand.projectId,
					targetBranch: attempt.targetBranch,
					taskId: cand.taskId,
					taskBranch: attempt.taskBranch,
					expectedTaskSha: attempt.expectedTaskSha,
					expectedTargetSha: attempt.expectedTargetSha,
					mergeAttemptId: attempt.mergeAttemptId,
				});
				let lease;
				try {
					lease = integrationQueue.acquire({
						projectId: cand.projectId,
						targetBranch: attempt.targetBranch,
						runnerId: runner.runnerId,
					});
				} catch (err) {
					claimStore.invalidate(cand.taskId);
					if (err?.code === "INTEGRATION_BUSY") {
						return { assigned: false, code: "INTEGRATION_BUSY" };
					}
					return sendStoreError(reply, err);
				}
				if (!lease.leased) {
					claimStore.invalidate(cand.taskId);
					misses.INTEGRATION_EMPTY = (misses.INTEGRATION_EMPTY || 0) + 1;
					continue;
				}
				return {
					assigned: true,
					projectId: cand.projectId,
					taskId: cand.taskId,
					runnerId: runner.runnerId,
					executionId,
					epoch,
					stageId: cand.stage?.id ?? null,
					kind: "integrate",
					integration: {
						taskBranch: attempt.taskBranch,
						expectedTaskSha: attempt.expectedTaskSha,
						targetBranch: attempt.targetBranch,
						expectedTargetSha: attempt.expectedTargetSha,
						mergeAttemptId: attempt.mergeAttemptId,
						integrationExecutionId: lease.executionId,
						integrationEpoch: lease.epoch,
					},
					requirements: req,
				};
			}
			try {
				const { executionId, epoch } = claimStore.claim(
					cand.taskId,
					runner.runnerId,
					cand.projectId,
				);
				// Stamp the matched harness/model/alias onto the task so the
				// timeline and reports attribute THIS run (mirrors the
				// embedded dispatch stamp); CI/merge stamp nothing.
				const candProject = projectStore.getProject(cand.projectId);
				stampDispatchRunAttribution({
					taskStore,
					project: candProject,
					task: cand.task,
					stage: cand.stage,
					stages: resolveStagesForTask(candProject, cand.task),
					req,
				});
				return {
					assigned: true,
					projectId: cand.projectId,
					taskId: cand.taskId,
					runnerId: runner.runnerId,
					executionId,
					epoch,
					stageId: cand.stage?.id ?? null,
					prompt: curateRunnerPrompt({ project: candProject, task: cand.task, stageId: cand.stage?.id }),
					...await ciPayloadFor(cand.projectId, cand.task, cand.stage),
					requirements: req,
				};
			} catch (err) {
				if (err?.code === "CLAIM_CONFLICT") continue;
				return sendStoreError(reply, err);
			}
		}
		return { assigned: false, code: "NO_CAPABLE_MATCH", misses };
	});

	// ---- Integration leases (Step 3: serialized Runner-run merges) ---------
	// The backend never merges or pushes: it queues merge requests
	// (enqueue is backend-internal, called by the merge stage) and leases
	// the head entry to one Runner per project + target branch. The Runner
	// holds `executionId`/`epoch` exactly like a task claim; a superseded
	// report is stale by construction.
	app.post("/runners/integration/acquire", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		// Paused Runners take no new work on any route (mirrors the claim
		// and dispatch routes), and the operator's Runs-merges switch and
		// project scope bind this direct lease exactly like a dispatched
		// merge: acquiring a merge lease must not bypass Settings.
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		const mergeVerdict = operatorConfigVerdict(
			runner,
			{ kind: "merge" },
			{ projectId: request.body?.projectId },
		);
		if (!mergeVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} settings refuse merge work (${mergeVerdict.reason}).`,
				code: mergeVerdict.reason,
			});
		}
		// Stage runnerPolicy binds the direct merge lease exactly like a
		// dispatched merge: peek the head queued entry (the lease about to
		// be granted), resolve its task's stage, and refuse Runners the
		// stage does not allow. Anything unresolvable fails open to the
		// legacy lease — an empty queue still reports leased:false below.
		const acquireProjectId = request.body?.projectId;
		const acquireBranch = request.body?.targetBranch;
		if (acquireProjectId && acquireBranch) {
			const headEntry = integrationQueue.peekHead({ projectId: acquireProjectId, targetBranch: acquireBranch });
			if (headEntry?.taskId) {
				const headTask = taskStore.getTask(acquireProjectId, headEntry.taskId);
				const headStages = resolveStagesForTask(projectStore.getProject(acquireProjectId), headTask);
				const headStage = (Array.isArray(headStages) ? headStages : []).find(
					(s) => String(s?.id) === String(headTask?.currentStageId),
				) || null;
				const leaseVerdict = stageRunnerPolicyVerdict(headStage, runner.runnerId);
				if (!leaseVerdict.ok) {
					return reply.status(409).send({
						error: `Runner ${runner.runnerId} is refused by this stage's Runner list (${leaseVerdict.reason}).`,
						code: leaseVerdict.reason,
					});
				}
			}
		}
		try {
			return integrationQueue.acquire({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				runnerId: runner.runnerId,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/integration/heartbeat", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			return integrationQueue.heartbeat({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/integration/report", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			const receipt = integrationQueue.report({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				outcome: request.body?.outcome,
				mergeSha: request.body?.mergeSha ?? null,
				detail: request.body?.detail ?? null,
			});
			return { ...receipt, runnerId: runner.runnerId };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners/integration", async (request) => {
		if (!integrationQueue) return { depth: 0, lease: null, counters: {} };
		return {
			...integrationQueue.describe({
				projectId: request.query?.projectId,
				targetBranch: request.query?.targetBranch,
			}),
			counters: integrationQueue.snapshot(),
		};
	});

	// ---- Steering acks (D5, ADR 0011) --------------------------------------
	// The unified POST /tasks/:id/steer (taskFlowRoutes) queues against the
	// live lease; the Runner pulls on heartbeat and acks here.
	app.post("/tasks/:id/steer-ack", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const hold = claimStore.describe(request.params.id);
			if (
				!hold ||
				hold.executionId !== request.body?.executionId ||
				hold.epoch !== request.body?.epoch ||
				hold.runnerId !== runner.runnerId
			) {
				return reply.status(409).send({
					error: `Ack targets a superseded execution (no matching live lease).`,
					code: "STALE_EPOCH",
				});
			}
			return steerStore.ack(request.body.executionId, request.body?.steerId, {
				ok: request.body?.ok,
				detail: request.body?.detail,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/tasks/:id/steers", async (request, reply) => {
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		const executionId = request.query?.executionId;
		if (!executionId || typeof executionId !== "string") {
			return reply.status(400).send({
				error: "steers requires an executionId query.",
				code: "INVALID_STEER_ARGS",
			});
		}
		return {
			taskId: request.params.id,
			executionId,
			pending: steerStore.pendingFor(executionId),
			receipts: steerStore.receiptsFor(executionId),
		};
	});
};

	 * MARK: heartbeat
	 * @description Renews a live integration lease. A stale or unknown
	 *   execution throws `STALE_EPOCH` so a zombie stops being propped up.
	 * @example q.heartbeat({ executionId: 'e', epoch: 3 }) => { executionId: 'e', epoch: 3 }
	 ***/
	heartbeat({ projectId, targetBranch, executionId, epoch }) {
		const { scope } = this._scope(projectId, targetBranch);
		const lease = this._reapLease(scope);
		if (!lease || lease.executionId !== executionId || lease.epoch !== epoch) {
			this.counters.staleRejected += 1;
			throw IntegrationQueue._stale("unknown or superseded integration execution");
		}
		lease.expiresAt = this.now() + this.ttlMs;
		return { executionId, epoch: lease.epoch };
	}

	/***
	 * MARK: report
	 * @description Records a Runner's terminal integration report and
	 *   releases the lease. `outcome` is one of `landed | conflict |
	 *   stale-head | needs-sync | failed`. Re-reporting a settled
	 *   execution is a no-op (`duplicate: true`); a report for a
	 *   superseded execution throws `STALE_EPOCH`.
	 * @example q.report({ projectId: 'p', targetBranch: 'main', executionId: 'e', epoch: 1, outcome: 'landed', mergeSha: 'abc' }) => { accepted: true }
	 ***/
	report({ projectId, targetBranch, executionId, epoch, outcome, mergeSha = null, detail = null }) {
		const valid = ["landed", "conflict", "stale-head", "needs-sync", "failed"];
		if (!valid.includes(outcome)) {
			throw IntegrationQueue._argError(`report requires outcome one of ${valid.join(" | ")}.`);
		}
		if (this.settled.has(executionId)) {
			this.counters.duplicateReports += 1;
			return { accepted: true, duplicate: true };
		}
		const { scope } = this._scope(projectId, targetBranch);
		const lease = scope.lease;
		if (!lease || lease.executionId !== executionId || lease.epoch !== epoch) {
			this.counters.staleRejected += 1;
			throw IntegrationQueue._stale("unknown or superseded integration execution");
		}
		scope.lease = null;
		lease.state = outcome;
		this.settled.set(executionId, {
			projectId,
			targetBranch,
			taskId: lease.taskId,
			outcome,
			mergeSha,
			detail,
			at: new Date().toISOString(),
		});
		if (outcome === "landed") this.counters.landed += 1;
		if (outcome === "conflict") this.counters.conflicts += 1;
		if (outcome === "stale-head") this.counters.staleHeads += 1;
		return { accepted: true, duplicate: false, outcome };
	}

	/***
	 * MARK: describe
	 * @description Queue depth + live lease for one scope (Runner monitor,
	 *   Step 6 observability). Lazy expiry applies before reading.
	 * @example q.describe({ projectId: 'p', targetBranch: 'main' }) => { depth: 1, lease: null }
	 ***/
	describe({ projectId, targetBranch }) {
		const { scope } = this._scope(projectId, targetBranch);
		const lease = this._reapLease(scope);
		return {
			depth: scope.queue.length,
			lease: lease
				? {
						taskId: lease.taskId,
						runnerId: lease.runnerId,
						executionId: lease.executionId,
						epoch: lease.epoch,
						expiresAt: lease.expiresAt,
					}
				: null,
		};
	}

	/***
	 * MARK: peekHead
	 * @description Returns a copy of the head queued entry for one scope
	 *   without leasing it, so the direct-acquire route can resolve the head
	 *   task's stage (and its runnerPolicy) before deciding the lease.
	 *   Returns null when the scope has no queued entry. Lazy expiry applies
	 *   before reading, like `describe`.
	 * @example q.peekHead({ projectId: 'p', targetBranch: 'main' }) => { taskId: 't', ... }
	 ***/
	peekHead({ projectId, targetBranch } = {}) {
		const { scope } = this._scope(projectId, targetBranch);
		this._reapLease(scope);
		const head = scope.queue[0] || null;
		return head ? { ...head } : null;
	}

	snapshot() {
		return { ...this.counters };
	}
